def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    opp_def = 0
    for x in opp:
        if x == 'D':
            opp_def += 1
    my_def = 0
    for x in me:
        if x == 'D':
            my_def += 1
    coop_rate = (n - opp_def) / float(n)
    recent_len = 8
    if n < recent_len:
        recent_len = n
    recent_def = 0
    recent_my_def = 0
    start = n - recent_len
    for i in range(start, n):
        if opp[i] == 'D':
            recent_def += 1
        if me[i] == 'D':
            recent_my_def += 1
    opp_d_streak = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        opp_d_streak += 1
        i -= 1
    my_d_streak = 0
    i = n - 1
    while i >= 0 and me[i] == 'D':
        my_d_streak += 1
        i -= 1
    remaining = 100 - n
    if remaining <= 0:
        return 'D'
    if n >= 2 and opp[-1] == 'C' and opp[-2] == 'C':
        if remaining == 1:
            return 'D'
        if remaining == 2:
            return 'C'
        if coop_rate > 0.55:
            return 'C'
        if rng.random() < 0.06:
            return 'D'
        return 'C'
    if last_opp == 'D':
        if opp_d_streak >= 3:
            if remaining <= 2:
                return 'D'
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if opp_d_streak == 2:
            if my_d_streak >= 2:
                if remaining <= 3:
                    return 'D'
                if rng.random() < 0.35:
                    return 'C'
                return 'D'
            return 'D'
        if my_d_streak == 0:
            if remaining <= 1:
                return 'D'
            return 'D'
        if my_d_streak >= 1:
            if coop_rate > 0.7 and recent_def <= 2:
                if rng.random() < 0.8:
                    return 'C'
                return 'D'
            if coop_rate > 0.45:
                if rng.random() < 0.45:
                    return 'C'
                return 'D'
            if rng.random() < 0.15:
                return 'C'
            return 'D'
    if opp_d_streak == 0:
        if n == 2:
            return 'C'
        if coop_rate < 0.35:
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        if coop_rate < 0.55:
            if my_def < opp_def:
                if rng.random() < 0.35:
                    return 'D'
                return 'C'
            if rng.random() < 0.2:
                return 'D'
            return 'C'
        if remaining == 1:
            return 'D'
        if remaining == 2:
            if coop_rate > 0.7:
                return 'C'
            return 'D'
        if remaining <= 4:
            if coop_rate > 0.8:
                return 'C'
            return 'D'
        if my_def > opp_def + 4:
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        if n > 20 and recent_def == 0 and recent_my_def >= 2:
            return 'C'
        if coop_rate > 0.88 and recent_def == 0:
            if rng.random() < 0.07:
                return 'D'
            return 'C'
        if rng.random() < 0.04:
            return 'D'
        return 'C'
    return 'C'
